function setMode(next){if(mode==='measure'&&draft.length>1&&next!=='measure'&&!confirm('El trazado no está guardado. ¿Descartarlo?'))return;mode=next;draft=[];offZoneDraft=null;if(next!=='pan')showMap();$('mapShell').classList.toggle('tool-mode',mode!=='pan');$('map').classList.toggle('tool',mode!=='pan');for(const[id,m]of [['addPoint','point'],['setCamp','camp'],['measureBtn','measure']])$(id).classList.toggle('active',mode===m);$('actionBar').hidden=mode==='pan';$('gpsMark').hidden=!gps||mode!=='pan';$('undoMeasure').hidden=mode!=='measure';$('saveTrace').hidden=mode!=='measure';$('cancelTool').textContent=mode==='measure'?'Terminar':'Cancelar';updateAction();map?.render(false);}
