function exportGPX(){const point=(f)=>{const p=f.properties,c=f.geometry.coordinates;const desc=[p.notes,p.depth_m!==null?`Profundidad registrada: ${p.depth_m} m`:'',p.observedAt?`Fecha: ${p.observedAt}`:'',p.waterReference?`Referencia agua: ${p.waterReference}`:'',`Origen: ${p.source}`].filter(Boolean).join('\n');return `<wpt lat="${c[1]}" lon="${c[0]}"><name>${esc(p.name)}</name><desc>${esc(desc)}</desc><type>${esc(p.kind)}</type><extensions><oa:id>${esc(f.id)}</oa:id><oa:verified>${p.verified?'1':'0'}</oa:verified><oa:createdAt>${esc(p.createdAt||'')}</oa:createdAt><oa:updatedAt>${esc(p.updatedAt||'')}</oa:updatedAt><oa:notes>${esc(p.notes)}</oa:notes><oa:source>${esc(p.source)}</oa:source>${p.depth_m!==null?`<oa:depth_m>${p.depth_m}</oa:depth_m>`:''}<oa:observedAt>${esc(p.observedAt)}</oa:observedAt><oa:waterReference>${esc(p.waterReference)}</oa:waterReference>${p.landmark?`<oa:landmark>${esc(p.landmark)}</oa:landmark>`:''}${p.bottom?`<oa:bottom>${esc(p.bottom)}</oa:bottom>`:''}</extensions></wpt>`;};const tracks=state.features.filter(f=>f.geometry.type==='LineString').map(f=>`<trk><name>${esc(f.properties.name)}</name><desc>${esc(f.properties.notes)}</desc><extensions><oa:id>${esc(f.id)}</oa:id></extensions><trkseg>${f.geometry.coordinates.map(c=>`<trkpt lat="${c[1]}" lon="${c[0]}"/>`).join('')}</trkseg></trk>`);const xml=`<?xml version="1.0" encoding="UTF-8"?>\n<gpx version="1.1" creator="Carp Field Notes" xmlns="http://www.topografix.com/GPX/1/1" xmlns:oa="urn:orellana-atlas:1"><metadata><name>Carp Field Notes</name><time>${new Date().toISOString()}</time></metadata>${state.features.filter(f=>f.geometry.type==='Point').map(point).join('')}${tracks.join('')}</gpx>`;shareOrDownload(`Orellana_${today()}.gpx`,xml,'application/gpx+xml','GPX de Carp Field Notes');}
