// --- Astronomía (algoritmos de baja precisión tipo SunCalc; error de pocos minutos) ---
const J1970=2440588,J2000=2451545,OBL=DEG*23.4397;
const toDays=t=>t/864e5-.5+J1970-J2000;
const raOf=(l,b)=>Math.atan2(Math.sin(l)*Math.cos(OBL)-Math.tan(b)*Math.sin(OBL),Math.cos(l)),decOf=(l,b)=>Math.asin(Math.sin(b)*Math.cos(OBL)+Math.cos(b)*Math.sin(OBL)*Math.sin(l));
function sunPos(d){const M=DEG*(357.5291+.98560028*d),L=M+DEG*(1.9148*Math.sin(M)+.02*Math.sin(2*M)+.0003*Math.sin(3*M))+DEG*102.9372+Math.PI;return {ra:raOf(L,0),dec:decOf(L,0)};}
function moonPos(d){const L=DEG*(218.316+13.176396*d),M=DEG*(134.963+13.064993*d),F=DEG*(93.272+13.22935*d),l=L+DEG*6.289*Math.sin(M),b=DEG*5.128*Math.sin(F);return {ra:raOf(l,b),dec:decOf(l,b)};}
